<div class="mb-8"><div class="text-sm text-gray-500">Editorial intelligence</div><h1 class="display text-4xl font-bold">AI studio</h1></div><form id="generator" class="grid lg:grid-cols-[1fr_1.2fr] gap-6"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="generation_prompt"><input type="hidden" name="generation_response"><input type="hidden" name="generation_provider"><input type="hidden" name="generation_model"><section class="bg-white rounded-2xl shadow-sm p-6"><h2 class="display text-xl font-bold mb-5">Source material</h2><select name="news_id" class="mb-5 w-full rounded-lg border border-gray-200 px-3 py-2"><?php foreach($items as $item): ?><option value="<?=$item['id']?>" <?=((int)($_GET['news_id']??0)===$item['id'])?'selected':''?>><?=e($item['title'])?> — <?=e($item['source_name'])?></option><?php endforeach; ?></select><div id="sourcePreview" class="rounded-xl bg-[#f6f5f1] p-4 text-sm text-gray-600 mb-5">Select a source to generate an original report. The original URL will be retained automatically.</div><label class="text-sm font-medium">Provider</label><select name="provider" class="mt-2 mb-5 w-full rounded-lg border border-gray-200 px-3 py-2"><?php foreach($providers as $name=>$ok): ?><option value="<?=$name?>" <?=$ok?'':'disabled'?>><?=ucfirst($name)?> <?=$ok?'':'(not configured)'?></option><?php endforeach; ?></select><input name="model" placeholder="Model (optional; provider default)" class="mb-5 w-full rounded-lg border border-gray-200 px-3 py-2"><div class="grid grid-cols-2 gap-4"><select name="style" class="w-full rounded-lg border border-gray-200 px-3 py-2"><option>Professional News</option><option>Breaking News</option><option>Technology</option><option>Business</option><option>Education</option><option>Politics</option></select><select name="length" class="w-full rounded-lg border border-gray-200 px-3 py-2"><option>Short</option><option selected>Medium</option><option>Long</option></select></div><textarea name="instructions" rows="4" class="mt-5 w-full rounded-lg border border-gray-200 px-3 py-2" placeholder="Additional editorial instructions…"></textarea><button id="generate" class="mt-5 w-full bg-[#101513] text-white rounded-lg py-3 font-semibold">Generate article</button></section><section class="bg-white rounded-2xl shadow-sm p-6"><h2 class="display text-xl font-bold mb-5">Editable result</h2><div id="empty" class="text-sm text-gray-500 py-16 text-center">Generate a report for review.</div><div id="editor" class="hidden space-y-4"><input name="title" placeholder="Headline" class="w-full display text-2xl font-bold border-b border-gray-200 pb-3"><textarea name="summary" placeholder="Summary" rows="3" class="w-full rounded-lg border border-gray-200 px-3 py-2"></textarea><textarea name="content" placeholder="Article body" rows="12" class="w-full rounded-lg border border-gray-200 px-3 py-2"></textarea><select name="category_id" class="w-full rounded-lg border border-gray-200 px-3 py-2"><option value="">Uncategorized</option><?php foreach($categories as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select><input name="tags" placeholder="Tags, comma separated" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input name="seo_title" placeholder="SEO title" class="w-full rounded-lg border border-gray-200 px-3 py-2"><textarea name="meta_description" placeholder="Meta description" rows="2" class="w-full rounded-lg border border-gray-200 px-3 py-2"></textarea><input name="featured_image" placeholder="Featured image URL (optional)" class="w-full rounded-lg border border-gray-200 px-3 py-2"><input type="hidden" name="source_url"><input type="hidden" name="source_name"><input type="hidden" name="news_id"><button type="button" id="save" class="bg-[#b8e64b] rounded-lg px-5 py-3 font-semibold">Save draft</button></div></section></form><script>const form=document.getElementById('generator'),csrf='<?=e(csrf_token())?>';form.onsubmit=async e=>{e.preventDefault();const b=document.getElementById('generate');b.disabled=true;b.textContent='Generating…';const r=await fetch('/api/generate',{method:'POST',body:new URLSearchParams(new FormData(form))});const d=await r.json();b.disabled=false;b.textContent='Generate article';if(!d.data){alert(d.error||'Generation failed');return;}document.getElementById('empty').classList.add('hidden');document.getElementById('editor').classList.remove('hidden');Object.entries(d.data).forEach(([k,v])=>{const el=form.elements[k];if(el)el.value=Array.isArray(v)?v.join(', '):v;});form.elements.source_url.value=d.source.url;form.elements.source_name.value=d.source.name;form.elements.news_id.value=d.source.news_id;form.elements.generation_prompt.value=d.prompt;form.elements.generation_response.value=d.response;form.elements.generation_provider.value=form.elements.provider.value;form.elements.generation_model.value=d.model;};document.getElementById('save').onclick=()=>{const f=document.createElement('form');f.method='post';f.action='/admin/articles/save';const data=new FormData(form);data.set('csrf',csrf);data.set('status','draft');data.set('ai_generated','1');for(const [k,v] of data){const i=document.createElement('input');i.name=k;i.value=v;f.appendChild(i);}document.body.appendChild(f);f.submit();};</script>
